const body = $input.first().json.body || {};
let a = body;
// Accepts a simple payload or a Prometheus Alertmanager webhook
if (Array.isArray(body.alerts) && body.alerts.length) {
  const x = body.alerts[0], l = x.labels || {}, n = x.annotations || {};
  a = { status: x.status, service: l.service || l.job, severity: l.severity, title: n.summary || l.alertname, description: n.description, source: 'alertmanager' };
}
const errors = [];
const serviceId = String(a.service || a.serviceId || '').trim().toLowerCase();
if (!/^[a-z0-9_.-]{1,64}$/.test(serviceId)) errors.push('service is required (letters, numbers, . _ -)');
const title = String(a.title || a.alertName || a.name || '').trim().slice(0, 200);
if (!title) errors.push('title is required');
const s = String(a.severity || '').toLowerCase();
const severity = /^(critical|sev1|p1|page|fatal)$/.test(s) ? 'SEV1' : /^(high|error|major|sev2|p2)$/.test(s) ? 'SEV2' : 'SEV3';
const st = String(a.status || 'firing').toLowerCase();
const route = errors.length ? 'invalid' : (/^(resolved|ok|recovered)$/.test(st) ? 'resolved' : 'firing');
const rnd = () => Math.random().toString(36).slice(2, 10) + Math.random().toString(36).slice(2, 10);
const incidentId = 'INC-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
return [{ json: { route, errors, serviceId, title, severity, description: String(a.description || '').slice(0, 1000), source: String(a.source || 'webhook'), alertJson: JSON.stringify(a).slice(0, 5000), incidentId, ackToken: rnd(), resolveToken: rnd() } }];

