const cfg = $('Set Continuity Config').first().json;
const n = $('Code - Normalize Alert').first().json;
const inc = $('Postgres - Open Or Attach Incident').first().json;
const svc = $input.first().json || {};
const parse = (v, d) => { if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return d; } } return v || d; };
const list = s => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
const sev = inc.severity;

// Who must be pulled in depends on severity: owner always, dependent teams from SEV2, executives and comms on SEV1
const resp = new Map();
const put = (email, role) => { if (email && !resp.has(email)) resp.set(email, role); };
put(svc.oncall_email || cfg.fallbackOncallEmail, 'service owner on-call');
if (sev !== 'SEV3') parse(svc.dependents, []).forEach(d => put(d.email, 'dependent team: ' + d.team));
if (sev !== 'SEV3' && svc.customer_facing) put(cfg.commsEmail, 'customer communications');
if (sev === 'SEV1') list(cfg.executiveEmails).forEach(e => put(e, 'executive notice'));

const channelName = ('inc-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-' + n.serviceId + '-' + inc.incident_id.slice(-4)).toLowerCase().replace(/[^a-z0-9_-]/g, '-').slice(0, 78);
return [{ json: { incidentId: inc.incident_id, severity: sev, serviceId: n.serviceId, serviceName: svc.name || n.serviceId, tier: svc.tier || 'n/a', title: n.title, description: n.description,
  source: n.source, channelName, responders: [...resp.entries()].map(([email, role]) => ({ email, role })), steps: parse(svc.runbook_steps, []), runbookUrl: svc.runbook_url || null,
  customerFacing: !!svc.customer_facing, ownerLead: svc.lead_email || null } }];

const cfg = $('Set Continuity Config').first().json;
const p = $('Code - Build Response Plan').first().json;
const n = $('Code - Normalize Alert').first().json;
const r = $input.first().json || {};
const channelId = (r.channel && r.channel.id) || cfg.defaultChannelId;      // falls back to the default channel if creation failed
const ackBase = cfg.publicWebhookBase + '/bc-ack?incidentId=' + encodeURIComponent(p.incidentId) + '&token=' + n.ackToken;
const checklist = ['Acknowledge the incident (link below) to become incident commander', 'Confirm impact and scope', ...p.steps, 'Post an update every ' + (p.severity === 'SEV1' ? 30 : 60) + ' minutes'];
const slackText = ':rotating_light: *' + p.severity + ' incident ' + p.incidentId + '*: ' + p.title + '\n*Service:* ' + p.serviceName + ' (tier ' + p.tier + ')' + (p.description ? '\n' + p.description : '') +
  '\n*Responders paged:* ' + p.responders.map(x => x.email).join(', ') + '\n*First response checklist:*\n' + checklist.map((s, i) => (i + 1) + '. ' + s).join('\n') +
  (p.runbookUrl ? '\n*Runbook:* ' + p.runbookUrl : '') + '\n*Acknowledge:* ' + ackBase +
  '\n*Resolve (commander only):* POST ' + cfg.publicWebhookBase + '/bc-resolve with {"incidentId":"' + p.incidentId + '","token":"' + n.resolveToken + '","summary":"..."}';
return [{ json: { ...p, channelId, ackBase, slackText } }];

