const p = $input.first().json;
// One email per person so every acknowledge link identifies who acknowledged
return p.responders.map(r => {
  const link = p.ackBase + '&responder=' + encodeURIComponent(r.email);
  const html = '<p><b>' + p.severity + ' incident ' + p.incidentId + '</b>: ' + String(p.title).replace(/</g, '&lt;') + '</p>' +
    '<p>Service: ' + p.serviceName + ' (tier ' + p.tier + ')<br>Your role: ' + r.role + '<br>War room: Slack #' + p.channelName + '</p>' +
    (p.steps.length ? '<p>First steps:</p><ol>' + p.steps.map(s => '<li>' + String(s).replace(/</g, '&lt;') + '</li>').join('') + '</ol>' : '') +
    (p.runbookUrl ? '<p>Runbook: <a href="' + p.runbookUrl + '">' + p.runbookUrl + '</a></p>' : '') +
    '<p><a href="' + link + '"><b>Acknowledge and take command</b></a></p>';
  return { json: { to: r.email, subject: '[' + p.severity + '] ' + p.title + ' (' + p.incidentId + ')', html } };
});

const q = $('Webhook - Acknowledge Incident').first().json.query || {};
const responder = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(q.responder || '')) ? String(q.responder).toLowerCase() : 'responder (via link)';
return [{ json: { incidentId: String(q.incidentId || '').trim(), token: String(q.token || '').trim(), responder } }];

