const b = $('Webhook - Resolve Incident').first().json.body || {};
const errors = [];
const incidentId = String(b.incidentId || '').trim(), token = String(b.token || '').trim();
const summary = String(b.summary || '').trim(), rootCause = String(b.rootCause || '').trim();
if (!incidentId || !token) errors.push('incidentId and token are required');
if (summary.length < 5 || summary.length > 1000) errors.push('summary must be 5-1000 characters');
if (rootCause.length > 1000) errors.push('rootCause is limited to 1000 characters');
return [{ json: { valid: errors.length === 0, errors, incidentId, token, summary, rootCause: rootCause.slice(0, 1000) } }];

