WITH u AS (
  UPDATE bc_incidents SET status = 'resolved', resolved_at = NOW(), resolution_summary = $3::text, root_cause = NULLIF($4::text, ''), updated_at = NOW()
  WHERE incident_id = $1::text AND resolve_token = $2::text AND status <> 'resolved' AND $5::boolean
  RETURNING incident_id, title, severity, service_id, slack_channel_id, declared_at, acknowledged_at, resolved_at, alert_count, resolution_summary
), e AS (
  INSERT INTO bc_incident_events (incident_id, event, actor, detail) SELECT incident_id, 'resolved', 'commander', resolution_summary FROM u RETURNING 1
)
SELECT u.*, ROUND((EXTRACT(EPOCH FROM (resolved_at - declared_at)) / 60)::numeric)::int AS duration_min,
       ROUND((EXTRACT(EPOCH FROM (acknowledged_at - declared_at)) / 60)::numeric)::int AS ack_min FROM u;

