const cfg = $('Set Continuity Config').first().json;
const v = $('Code - Validate Resolve Request').first().json;
const r = $input.first().json || {};
const ok = r.incident_id !== undefined;
if (!ok) return [{ json: { ok: false, reason: v.valid ? 'unknown incident, invalid token or already resolved' : v.errors.join('; ') } }];
const due = new Date(Date.now() + Number(cfg.postmortemDays) * 86400000).toISOString().slice(0, 10);
const list = s => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
const to = [...new Set([...list(cfg.stakeholderEmails), ...(r.severity === 'SEV1' ? list(cfg.executiveEmails) : [])])].join(',');
const dur = r.duration_min + ' min' + (r.ack_min !== null && r.ack_min !== undefined ? ' (acknowledged after ' + r.ack_min + ' min)' : ' (never acknowledged)');
const slackText = ':white_check_mark: *' + r.severity + ' incident ' + r.incident_id + ' resolved*: ' + r.title + '\nDuration: ' + dur + ' | alerts received: ' + r.alert_count +
  '\nSummary: ' + r.resolution_summary + (v.rootCause ? '\nRoot cause: ' + v.rootCause : '') + '\nPost-incident review due by ' + due + '.';
const html = '<p><b>' + r.severity + ' incident ' + r.incident_id + ' is resolved.</b></p><p>' + String(r.title).replace(/</g, '&lt;') + '</p>' +
  '<p>Duration: ' + dur + '<br>Summary: ' + String(r.resolution_summary).replace(/</g, '&lt;') + (v.rootCause ? '<br>Root cause: ' + String(v.rootCause).replace(/</g, '&lt;') : '') + '</p>' +
  '<p>A post-incident review is due by <b>' + due + '</b>.</p>';
return [{ json: { ok: true, incidentId: r.incident_id, durationMin: r.duration_min, channelId: r.slack_channel_id || cfg.defaultChannelId, slackText, to, subject: '[Resolved] ' + r.title + ' (' + r.incident_id + ')', html } }];

const cfg = $('Set Continuity Config').first().json;
const rows = $input.all().map(i => i.json);
return rows.map(r => {
  // Level 1 team lead, level 2 engineering director, level 3 CTO (stays at the top after that)
  const chain = [r.owner_lead, cfg.directorEmail, cfg.ctoEmail].filter(Boolean);
  const level = Number(r.escalation_level) + 1;
  const to = chain[Math.min(level, chain.length) - 1] || cfg.fallbackOncallEmail;
  const link = cfg.publicWebhookBase + '/bc-ack?incidentId=' + encodeURIComponent(r.incident_id) + '&token=' + r.ack_token + '&responder=' + encodeURIComponent(to);
  const text = ':warning: *Escalation level ' + level + '*: ' + r.severity + ' incident ' + r.incident_id + ' (' + r.title + ') has had no acknowledgement for ' + r.open_min + ' min. Escalated to ' + to + '.';
  const html = '<p><b>Escalation level ' + level + ':</b> ' + r.severity + ' incident <b>' + r.incident_id + '</b> is unacknowledged after ' + r.open_min + ' minutes.</p><p>' +
    String(r.title).replace(/</g, '&lt;') + '</p><p><a href="' + link + '"><b>Acknowledge and take command</b></a></p>';
  return { json: { incidentId: r.incident_id, level, to, channelId: r.slack_channel_id || cfg.defaultChannelId, subject: '[ESCALATION L' + level + '][' + r.severity + '] ' + r.title, html, slackText: text } };
});

