const cfg = $('Set Continuity Config').first().json;
const list = s => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
return $input.all().map(i => i.json).map(r => {
  const next = r.severity === 'SEV1' ? cfg.updateMinutesSev1 : cfg.updateMinutesSev2;
  const state = r.acknowledged_by ? 'commander: ' + r.acknowledged_by : 'NOT yet acknowledged';
  const to = [...new Set([...list(cfg.stakeholderEmails), ...(r.severity === 'SEV1' ? list(cfg.executiveEmails) : [])])].join(',');
  const text = ':information_source: *Status update ' + r.incident_id + '* (' + r.severity + '): ' + r.title + '\nOpen for ' + r.open_min + ' min | ' + state + ' | alerts: ' + r.alert_count + '\nLatest: ' + (r.last_event || 'no activity recorded') + '\nNext update in ' + next + ' min. Commander: reply in this channel with progress.';
  const html = '<p><b>Status update: ' + r.severity + ' incident ' + r.incident_id + '</b></p><p>' + String(r.title).replace(/</g, '&lt;') + '</p><p>Open for ' + r.open_min + ' min, ' + state + '.<br>Latest: ' + String(r.last_event || 'no activity recorded').replace(/</g, '&lt;') + '</p><p>Next update in ' + next + ' minutes.</p>';
  return { json: { incidentId: r.incident_id, channelId: r.slack_channel_id || cfg.defaultChannelId, to, subject: '[Update][' + r.severity + '] ' + r.title + ' (' + r.incident_id + ')', html, slackText: text } };
});

